// Parse: winget list (fixed-width text) -> one item { run_id, now, rows[] }
const input = $input.first();

function decode(buf) {
  if (buf.length >= 2 && buf[0] === 0xff && buf[1] === 0xfe) return buf.toString('utf16le').slice(1);
  if (buf.length >= 3 && buf[0] === 0xef && buf[1] === 0xbb && buf[2] === 0xbf) return buf.toString('utf8').slice(1);
  let zeros = 0;
  for (let i = 1; i < Math.min(buf.length, 400); i += 2) if (buf[i] === 0) zeros++;
  if (zeros > 50) return buf.toString('utf16le');
  return buf.toString('utf8');
}

let text = String(input.json.inventory_text || '');
if (!text.trim() && input.binary) {
  const key = Object.keys(input.binary)[0];
  if (key) text = decode(await this.helpers.getBinaryDataBuffer(0, key));
}
if (!text.trim()) throw new Error('Порожні вхідні дані: завантажте файл або вставте текст winget list');

const lines = text.split(/\r?\n/).map(l => l.split('\r').pop());
const dashIdx = lines.findIndex(l => /^-{20,}\s*$/.test(l));
if (dashIdx < 1) throw new Error('Не знайдено заголовок таблиці winget list (рядок з дефісами)');

const header = lines[dashIdx - 1];
const starts = [];
for (const m of header.matchAll(/\S+/g)) starts.push(m.index);
const names = starts.length >= 5
  ? ['name', 'id', 'version', 'available', 'source']
  : ['name', 'id', 'version', 'source'];

function djb2(s) {
  let h = 5381;
  for (const ch of s) h = ((h * 33) ^ ch.codePointAt(0)) >>> 0;
  return h.toString(16).padStart(8, '0');
}
function normName(s) {
  return s.toLowerCase().replace(/…$/, '').replace(/\d+(\.\d+)+(-\d+)?/g, ' ')
    .replace(/\s+/g, ' ').trim();
}
function archOf(id) {
  const m = id.match(/^ARP\\(?:Machine|User)\\(X64|X86|ARM64)\\/i)
    || id.match(/_(x64|x86|arm64|neutral)_/i)
    || id.match(/\.(x64|x86|arm64)$/i);
  return m ? m[1].toLowerCase() : '';
}
function keyOf(id, name) {
  const idTrunc = id.endsWith('…');
  const clean = id.replace(/…$/, '');
  if (/^msix\\/i.test(clean) && clean.includes('_')) return clean.split('_')[0].toLowerCase();
  if (idTrunc) return clean.toLowerCase() + '#' + djb2(normName(name));
  return clean.toLowerCase();
}

const byKey = new Map();
for (const line of lines.slice(dashIdx + 1)) {
  if (!line.trim()) continue;
  const rec = {};
  names.forEach((n, i) => {
    rec[n] = line.slice(starts[i], i + 1 < starts.length ? starts[i + 1] : undefined).trim();
  });
  if (!rec.name || !rec.id) continue;
  const key = keyOf(rec.id, rec.name);
  const sourceType = /^ARP\\/i.test(rec.id) ? 'arp' : /^MSIX\\/i.test(rec.id) ? 'msix'
    : (rec.source || '').toLowerCase() === 'winget' ? 'winget' : 'other';
  const prev = byKey.get(key);
  if (prev) {
    prev.instances += 1;
    if (!prev.versions.includes(rec.version)) prev.versions.push(rec.version);
    if (!prev.available_version && rec.available) prev.available_version = rec.available;
    const arch = archOf(rec.id);
    if (arch && !prev.archs.includes(arch)) prev.archs.push(arch);
    continue;
  }
  const arch = archOf(rec.id);
  byKey.set(key, {
    package_key: key,
    package_id: rec.id,
    name: rec.name,
    versions: [rec.version],
    available_version: rec.available || '',
    source_type: sourceType,
    archs: arch ? [arch] : [],
    truncated: rec.name.endsWith('…') || rec.id.endsWith('…'),
    instances: 1,
  });
}

const rows = [...byKey.values()].map(r => ({
  package_key: r.package_key,
  package_id: r.package_id,
  name: r.name,
  version: r.versions.join('; '),
  available_version: r.available_version,
  source_type: r.source_type,
  arch: r.archs.join(','),
  truncated: r.truncated,
  instances: r.instances,
})).sort((a, b) => a.package_key.localeCompare(b.package_key));

const now = new Date().toISOString();
return [{ json: { run_id: 'run-' + now.replace(/[-:.TZ]/g, '').slice(0, 14), now, source_lines: lines.length, rows } }];

// Match: dictionary -> alias rules -> AI queue. Emits one item per AI batch, or one {skip:true}.
const MODEL = 'claude-opus-5';
const BATCH_SIZE = 150;

const parsed = $('Parse').first().json;
const categories = $('Load categories').all().map(i => i.json).filter(r => r.code)
  .sort((a, b) => a.code.localeCompare(b.code));
const software = $('Load software').all().map(i => i.json).filter(r => r.software_key);
const packages = $('Load packages').all().map(i => i.json).filter(r => r.package_key);

const softwareByKey = Object.fromEntries(software.map(s => [s.software_key, s]));
const packageByKey = Object.fromEntries(packages.map(p => [p.package_key, p]));

const aliasRules = [];
for (const s of software) {
  for (const raw of String(s.aliases || '').split('|')) {
    const a = raw.trim().toLowerCase();
    const m = a.match(/^(id|name):(.+)$/);
    if (m) aliasRules.push({ field: m[1], prefix: m[2], software_key: s.software_key });
  }
}
aliasRules.sort((a, b) => b.prefix.length - a.prefix.length || a.software_key.localeCompare(b.software_key));

const matched = [];
const unknown = [];
for (const row of parsed.rows) {
  const prev = packageByKey[row.package_key];
  if (prev && prev.software_key && softwareByKey[prev.software_key] && prev.match_method !== 'fallback') {
    matched.push({ ...row, software_key: prev.software_key, match_method: prev.match_method || 'dictionary',
      confidence: prev.confidence ?? 1, reason: prev.reason || '', needs_review: !!prev.needs_review });
    continue;
  }
  const id = row.package_id.toLowerCase();
  const name = row.name.toLowerCase();
  const rule = aliasRules.find(r => (r.field === 'id' ? id : name).startsWith(r.prefix));
  if (rule) {
    matched.push({ ...row, software_key: rule.software_key, match_method: 'rule', confidence: 1,
      reason: `alias ${rule.field}:${rule.prefix}`, needs_review: false });
    continue;
  }
  unknown.push(row);
}

const categoryCodes = categories.map(c => c.code);
const system = [
  'You classify installed Windows software packages (from `winget list`) into a software catalog.',
  'Definitions: SOFTWARE is a product a person knowingly installs or buys (e.g. "Microsoft Office", "Python", "Mozilla Firefox").',
  'A PACKAGE is one installed component or variant of a product (e.g. "Microsoft Word" and "Office Click-to-Run" are packages of "Microsoft Office"; "Python Launcher" is a package of "Python"; "Mozilla Maintenance Service" is a package of "Mozilla Firefox"; the same game from Steam and from another store is one software).',
  'Group all components/add-ins/services/drivers/updaters of one product under ONE software. Different major versions of the same product are the same software (Python 3.12 and 3.14 -> "Python").',
  'An add-in for product A made for product B belongs to the product it extends the functionality of (e.g. "Microsoft Teams Meeting Add-in for Microsoft Office" -> "Microsoft Teams").',
  'Built-in Windows apps that a user perceives as separate apps (Calculator, Paint, Notepad, Camera, Photos...) are separate software with vendor Microsoft. Use their canonical English product names (e.g. "Windows Calculator").',
  'If a package belongs to software already in the catalog, return its existing_software_key. Otherwise return existing_software_key as an empty string and give a canonical English software_name without version numbers, edition or architecture.',
  'category_code must be one of the listed codes; pick the category of the SOFTWARE, not of the component. Use "other" only when nothing fits.',
  'confidence is 0..1: how sure you are about the software grouping AND category. reason: max 12 words.',
  'Return exactly one result per input package_key, in the input order.',
  '',
  'Categories (code: name — description):',
  ...categories.map(c => `- ${c.code}: ${c.name_uk} — ${c.description}`),
].join('\n');

const catalog = software
  .map(s => ({ software_key: s.software_key, name: s.name, vendor: s.vendor, category_code: s.category_code }))
  .sort((a, b) => a.software_key.localeCompare(b.software_key));

const resultProps = {
  package_key: { type: 'string' },
  existing_software_key: { type: 'string' },
  software_name: { type: 'string' },
  vendor: { type: 'string' },
  category_code: { type: 'string', enum: categoryCodes },
  confidence: { type: 'number' },
  reason: { type: 'string' },
};
const item = { type: 'object', additionalProperties: false, required: Object.keys(resultProps), properties: resultProps };
const schema = { type: 'object', additionalProperties: false, required: ['results'],
  properties: { results: { type: 'array', items: item } } };

const batches = [];
for (let i = 0; i < unknown.length; i += BATCH_SIZE) {
  const chunk = unknown.slice(i, i + BATCH_SIZE);
  const payload = chunk.map(r => ({ package_key: r.package_key, name: r.name, package_id: r.package_id,
    source_type: r.source_type, version: r.version }));
  batches.push({
    skip: false,
    keys: chunk.map(r => r.package_key),
    request: {
      model: MODEL,
      max_tokens: 32000,
      fallbacks: 'default',
      output_config: { effort: 'low', format: { type: 'json_schema', schema } },
      system,
      messages: [{ role: 'user', content:
        'Existing software catalog:\n' + JSON.stringify(catalog) +
        '\n\nPackages to classify:\n' + JSON.stringify(payload) }],
    },
  });
}

// ctx rides on the first item only — Finalize reads it from there
const items = batches.length ? batches : [{ skip: true }];
items[0].ctx = { run_id: parsed.run_id, now: parsed.now, matched, unknown, categories, catalog };
return items.map(json => ({ json }));

// Finalize: validate AI answers, build software/package rows, detect removed packages, run stats.
const REVIEW_THRESHOLD = 0.7;

const matchItems = $('Match').all().map(i => i.json);
const ctx = matchItems[0].ctx;
const packages = $('Load packages').all().map(i => i.json).filter(r => r.package_key);

const categoryCodes = new Set(ctx.categories.map(c => c.code));
const softwareKeys = new Set(ctx.catalog.map(s => s.software_key));
const packageByKey = Object.fromEntries(packages.map(p => [p.package_key, p]));

function slug(s) {
  return String(s).normalize('NFKD').replace(/\p{M}+/gu, '').toLowerCase()
    .replace(/\+\+/g, 'pp').replace(/[^a-z0-9а-яіїєґ]+/g, '-').replace(/^-+|-+$/g, '') || 'unknown';
}
function clamp01(x) { const n = Number(x); return Number.isFinite(n) ? Math.min(1, Math.max(0, n)) : 0; }

// --- collect AI results by package_key
const aiResults = {};
const batchErrors = [];
const responses = matchItems[0].skip ? [] : $input.all().map(i => i.json);
responses.forEach((resp, i) => {
  const keys = new Set(matchItems[i]?.keys || []);
  try {
    if (resp.error) throw new Error(typeof resp.error === 'string' ? resp.error
      : [resp.error.message, resp.error.description].filter(Boolean).join(': ').slice(0, 300));
    if (resp.stop_reason !== 'end_turn') throw new Error('stop_reason=' + resp.stop_reason);
    const textBlock = (resp.content || []).find(b => b.type === 'text');
    const parsed = JSON.parse(textBlock.text);
    for (const r of parsed.results || []) if (keys.has(r.package_key) && !aiResults[r.package_key]) aiResults[r.package_key] = r;
  } catch (e) {
    batchErrors.push(`batch ${i}: ${e.message}`);
  }
});

// --- resolve software for unknown packages
const newSoftware = {};
const resolved = ctx.unknown.map(row => {
  const r = aiResults[row.package_key];
  // no software is created: the package goes back to the AI queue on the next run
  if (!r) return { ...row, software_key: '', match_method: 'fallback', confidence: 0,
    reason: 'AI не повернув результат', needs_review: true };

  const confidence = clamp01(r.confidence);
  const validCategory = categoryCodes.has(r.category_code);
  const key = softwareKeys.has(r.existing_software_key) ? r.existing_software_key : slug(r.software_name);
  // ponytail: first answer wins for a new software key; later duplicates keep their own confidence on the package row
  if (!softwareKeys.has(key) && !newSoftware[key]) {
    newSoftware[key] = { software_key: key, name: r.software_name, vendor: r.vendor || '',
      category_code: validCategory ? r.category_code : 'other', aliases: '', source: 'ai',
      confidence, locked: false, needs_review: confidence < REVIEW_THRESHOLD || !validCategory };
  }
  return { ...row, software_key: key, match_method: 'ai', confidence,
    reason: String(r.reason || '').slice(0, 200), needs_review: confidence < REVIEW_THRESHOLD };
});

// --- package rows: only what this file contains; rows from other machines are left untouched
// ponytail: the catalog holds no per-machine state, so `version` is the one last seen.
// Add a `host` column and key rows by host + package_key if you need "installed where".
let newPackages = 0, updatedPackages = 0;
const packageRows = [...ctx.matched, ...resolved].map(row => {
  const prev = packageByKey[row.package_key];
  if (!prev) newPackages++;
  else if (prev.version !== row.version || (prev.available_version || '') !== row.available_version
    || !prev.is_installed || prev.software_key !== row.software_key) updatedPackages++;
  return { ...row, is_installed: true,
    first_seen: prev?.first_seen || ctx.now, last_seen: ctx.now, last_run_id: ctx.run_id };
});

const softwareRows = Object.values(newSoftware).sort((a, b) => a.software_key.localeCompare(b.software_key));
const run = {
  run_id: ctx.run_id, started_at: ctx.now, total: packageRows.length,
  new_packages: newPackages, updated_packages: updatedPackages,
  removed_packages: packages.length - packageRows.filter(r => packageByKey[r.package_key]).length,
  new_software: softwareRows.length, ai_calls: responses.length,
  needs_review: packageRows.filter(r => r.is_installed && r.needs_review).length,
};

// --- readable breakdown: category -> software -> its packages
const allSoftware = Object.fromEntries([...ctx.catalog, ...Object.values(newSoftware)].map(s => [s.software_key, s]));
const catName = Object.fromEntries(ctx.categories.map(c => [c.code, c.name_uk]));
const grouped = {};
for (const r of packageRows.filter(r => r.is_installed)) {
  const s = allSoftware[r.software_key];
  const bucket = (grouped[s?.category_code || 'other'] ??= {});
  const label = s ? s.name : '❓ ПЗ не визначено';
  (bucket[label] ??= []).push(r.name.replace(/…$/, '') + (r.instances > 1 ? ` ×${r.instances}` : ''));
}
const report = Object.keys(grouped).sort((a, b) => (catName[a] || a).localeCompare(catName[b] || b)).map(code => {
  const names = Object.keys(grouped[code]).sort((a, b) => a.localeCompare(b));
  const packages = names.reduce((n, name) => n + grouped[code][name].length, 0);
  return [`▐ ${catName[code] || code} — ПЗ: ${names.length}, пакетів: ${packages}`,
    ...names.map(name => {
      const list = grouped[code][name];
      return list.length === 1 && list[0] === name ? `   ${name}` : `   ${name}: ${list.join(', ')}`;
    })].join('\n');
}).join('\n\n');

const summary = [
  `Запуск ${run.run_id}`,
  `Пакетів у файлі: ${run.total}`,
  `Нових пакетів: ${run.new_packages}; оновлених: ${run.updated_packages}`,
  `У довіднику з інших файлів: ${run.removed_packages}`,
  `Нового ПЗ: ${run.new_software}; викликів AI: ${run.ai_calls}`,
  `На ручну перевірку: ${run.needs_review}`,
  ...batchErrors.map(e => `Помилка AI — ${e}`),
  '',
  report,
].join('\n');

return [{ json: { run, summary, report, batch_errors: batchErrors, softwareRows, packageRows } }];
